MIX = {'desalinated': 60, 'groundwater': 25, 'other and storage': 15}
print('Illustrative supply mix (percent, model):')
for k, v in MIX.items():
    print('%s: %d' % (k, v))
print('Total: %d percent' % sum(MIX.values()))
print('Note: model mix only; real shares need an official water balance.')

SCORES = {'shade and cooling': 8, 'drainage': 7, 'water reuse': 6, 'early warning': 9}
print('Adaptation scores (model, 0 to 10):')
for k, v in SCORES.items():
    print('%s: %d' % (k, v))
print('Mean score: %.2f' % (sum(SCORES.values()) / len(SCORES)))
print('Weakest measure: %s' % min(SCORES, key=SCORES.get))
